pub const Reader = struct {
    buf: []u8,
    remain: []u8,
    allocator: std.mem.Allocator,

pub fn init(buf: []u8, allocator: std.mem.Allocator) Reader {
            return Reader{ .buf = buf, .remain = buf, .allocator = allocator };
    }

pub fn read(self: *Reader, count: usize) ![]u8 {
            const read_count = @min(count, self.remain.len);
            if ((read_count < count)) {
                return error.EOF;
            }
            const slice = self.remain[0..read_count];
            self.remain = self.remain[read_count..];
            return slice;
    }

pub inline fn readAs(self: *Reader, comptime T: type) !T {
            if ((!std.meta.hasUniqueRepresentation(T))) {
                _ = @compileError(std.fmt.comptimePrint("{s} must have unique representation.", .{ @typeName(T) }));
            }
            return std.mem.bytesAsValue(T, try self.read(@sizeOf(T)));
    }

pub inline fn readByte(self: *Reader) !u8 {
            const slice = try self.read(1);
            return slice[0];
    }

pub fn readEnum(self: *Reader, comptime Enum: type) !Enum {
            const type_info = @typeInfo(Enum).Enum;
            const tag = try self.readInt(type_info.tag_type);
            inline for (std.meta.fields(Enum)) |field| {
                if ((tag == @field(field, "value"))) {
                    return @field(Enum, @field(field, "name"));
                }
            }
            return error.InvalidValue;
    }

pub fn readArray(self: *Reader, comptime T: type) ![]const T {
            const length = try self.readInt(u32);
            if ((length == 0)) {
                return (&.{  });
            }
            if (T == u8) {
return try self.read(length);
} else if ((T == u16) or (T == u32) or (T == i8) or (T == i16) or (T == i32)) {
return std.mem.readIntSliceNative(T, self.read((length * @sizeOf(T))));
} else if ((T == ConstSentinelBytes) or (T == ConstBytes)) {
var array = try self.allocator.alloc(T, length);
            _ = &array;
            {
                var i: i32 = 0;
                _ = &i;
                const __end_0 = array.len;
                while (i < __end_0) : (i += 1) {
                    array[cp_cast_int(usize, i)] = try self.readArray(u8);
                }
            }
            return array;
} else {
switch (@typeInfo(T)) {
.Struct => |Struct| {
switch (Struct.layout) {
.Packed => {
const sizeof = @sizeOf(T);
            const slice = try self.read((sizeof * length));
            return std.mem.bytesAsSlice(T, slice);
},
else => {

},
}
},
.Enum => |type_info| {
const enum_values = try self.read((length * @sizeOf(type_info.tag_type)));
            {
                return @as([*]T, @ptrCast(@alignCast(enum_values.ptr)))[0..length];
            }
},
else => {

},
}
            var array = try self.allocator.alloc(T, length);
            _ = &array;
            {
                var i: i32 = 0;
                _ = &i;
                const __end_1 = array.len;
                while (i < __end_1) : (i += 1) {
                    array[cp_cast_int(usize, i)] = try self.readValue(T);
                }
            }
            return array;
}
    }

pub inline fn readByteArray(self: *Reader) ![]u8 {
            const length = try self.readInt(u32);
            if ((length == 0)) {
                return (&.{  });
            }
            return try self.read((if (comptime @typeInfo(@TypeOf(length)) == .@"enum") cp_cast_int(usize, @intFromEnum(length)) else cp_cast_int(usize, length)));
    }

pub inline fn readInt(self: *Reader, comptime T: type) !T {
            const slice = try self.read(@sizeOf(T));
            return std.mem.readIntSliceNative(T, slice);
    }

pub inline fn readBool(self: *Reader) !bool {
            return (try self.readByte() > 0);
    }

pub inline fn readValue(self: *Reader, comptime T: type) !T {
            if (T == bool) {
return try self.readBool();
} else if (T == u8) {
return try self.readByte();
} else if ((T == CStrConst) or (T == ConstSentinelBytes) or (T == ConstBytes)) {
return try self.readArray(u8);
} else if ((T == []const ConstSentinelBytes) or (T == []const CStrConst) or (T == []const ConstBytes)) {
return try self.readArray(ConstBytes);
} else if ((T == MutBytes) or (T == SentinelBytes) or (T == CStrMut)) {
return try self.readArray(MutBytes);
} else if ((T == u16) or (T == u32) or (T == i8) or (T == i16) or (T == i32)) {
return std.mem.readIntSliceNative(T, try self.read(@sizeOf(T)));
} else {
switch (@typeInfo(T)) {
.Struct => |Struct| {
switch (Struct.layout) {
.Packed => {
const sizeof = @sizeOf(T);
            const slice = try self.read(sizeof);
            return std.mem.bytesToValue(T, slice[0..sizeof]);
},
else => {

},
}
},
.Enum => {
return try self.readEnum(T);
},
else => {

},
}
            return try T.decode(self);
}
            _ = @compileError("Invalid type passed to readValue");
    }
    const Self = @This();
    pub const ReadError = ReaderReadError;
};

