pub const NpmRegistryParser = struct {
    log: *bun.logger.Log,
    source: *const bun.logger.Source,
    allocator: std.mem.Allocator,

pub fn addError(self: *NpmRegistryParser, loc: bun.logger.Loc, comptime text: []const u8) !void {
            _ = ((self.log.addError(self.source, loc, text)) catch unreachable);
            return error.ParserError;
    }

pub fn expectString(self: *NpmRegistryParser, expr: js_ast.Expr) !void {
            switch (expr.data) {
.e_string => {

},
else => {
const tag: js_ast.Expr.Tag = expr.data;
            _ = ((self.log.addErrorFmt(self.source, expr.loc, self.allocator, "expected string but received {}", .{ tag })) catch unreachable);
            return error.ParserError;
},
}
    }

pub fn parseRegistryURLString(self: *NpmRegistryParser, str: *js_ast.E.String) OOM!NpmRegistry {
            return try self.parseRegistryURLStringImpl(str.data);
    }

pub fn parseRegistryURLStringImpl(self: *NpmRegistryParser, str: []const u8) OOM!NpmRegistry {
            const url = bun.URL.parse(str);
            var registry = std.mem.zeroes(NpmRegistry);
            _ = &registry;
            if (((url.username.len == 0) and (url.password.len > 0))) {
                registry.token = url.password;
                registry.url = try std.fmt.allocPrint(self.allocator, "{s}://{f}/{s}/", .{ url.displayProtocol(), url.displayHost(), std.mem.trim(u8, url.pathname, "/") });
            } else {
                if (((url.username.len > 0) and (url.password.len > 0))) {
                    registry.username = url.username;
                    registry.password = url.password;
                    registry.url = try std.fmt.allocPrint(self.allocator, "{s}://{f}/{s}/", .{ url.displayProtocol(), url.displayHost(), std.mem.trim(u8, url.pathname, "/") });
                } else {
                    registry.url = url.href;
                }
            }
            return registry;
    }

pub fn parseRegistryObject(self: *NpmRegistryParser, obj: *js_ast.E.Object) !NpmRegistry {
            var registry = std.mem.zeroes(NpmRegistry);
            _ = &registry;
            if (obj.get("url")) |url| {
                _ = &url;
                _ = try self.expectString(url);
                const href = (url.asString(self.allocator)).?;
                registry.url = href;
            }
            if (obj.get("username")) |username| {
                _ = &username;
                _ = try self.expectString(username);
                registry.username = (username.asString(self.allocator)).?;
            }
            if (obj.get("password")) |password| {
                _ = &password;
                _ = try self.expectString(password);
                registry.password = (password.asString(self.allocator)).?;
            }
            if (obj.get("token")) |token| {
                _ = &token;
                _ = try self.expectString(token);
                registry.token = (token.asString(self.allocator)).?;
            }
            return registry;
    }

pub fn parseRegistry(self: *NpmRegistryParser, expr: js_ast.Expr) !NpmRegistry {
            switch (expr.data) {
.e_string => |str| {
return self.parseRegistryURLString(str);
},
.e_object => |obj| {
return self.parseRegistryObject(obj);
},
else => {
_ = try self.addError(expr.loc, "Expected registry to be a URL string or an object");
            return std.mem.zeroes(NpmRegistry);
},
}
    }
};

